import java.util.ArrayList;
import java.util.List;

public class Solution {
    static class ContaBancaria {
        private final String titular;
        private double saldo;
        private final List<String> historico = new ArrayList<>();

        ContaBancaria(String titular, double saldoInicial) {
            if (titular == null || titular.isBlank()) {
                throw new IllegalArgumentException("titular obrigatorio");
            }
            if (saldoInicial < 0) {
                throw new IllegalArgumentException("saldo inicial negativo");
            }
            this.titular = titular;
            this.saldo = saldoInicial;
            historico.add("abertura: " + saldoInicial);
        }

        void depositar(double valor) {
            exigirPositivo(valor);
            saldo += valor;
            historico.add("deposito: " + valor);
        }

        void sacar(double valor) {
            exigirPositivo(valor);
            if (valor > saldo) throw new IllegalStateException("saldo insuficiente");
            saldo -= valor;
            historico.add("saque: " + valor);
        }

        double saldo() { return saldo; }

        List<String> historico() { return List.copyOf(historico); }

        private void exigirPositivo(double valor) {
            if (valor <= 0) throw new IllegalArgumentException("valor deve ser positivo");
        }
    }
}

