import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class SolutionTest {
    @Test void depositoESaque() {
        var c = new Solution.ContaBancaria("Ana", 100);
        c.sacar(30); c.depositar(10);
        assertEquals(80, c.saldo());
        assertEquals(3, c.historico().size());
    }

    @Test void saldoInsuficiente() {
        var c = new Solution.ContaBancaria("Ana", 10);
        assertThrows(IllegalStateException.class, () -> c.sacar(11));
    }

    @Test void valoresInvalidos() {
        assertThrows(IllegalArgumentException.class, () -> new Solution.ContaBancaria("", 0));
        assertThrows(IllegalArgumentException.class, () -> new Solution.ContaBancaria("Ana", -1));
        var c = new Solution.ContaBancaria("Ana", 10);
        assertThrows(IllegalArgumentException.class, () -> c.depositar(0));
    }

    @Test void historicoImutavel() {
        var c = new Solution.ContaBancaria("Ana", 10);
        assertThrows(UnsupportedOperationException.class, () -> c.historico().add("hack"));
    }
}
